-- Códigos de acesso de uso único para o cadastro de organizador.
-- A tabela guarda só o hash. O texto puro fica fora do git, em
-- signup-codes.local.txt. Sem policy para anon/authenticated: só a
-- service role, no Route Handler de signup, reserva e consome o código.

create table public.signup_codes (
  id uuid primary key default gen_random_uuid(),
  code_hash text not null unique,
  used_at timestamptz,
  used_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);

alter table public.signup_codes enable row level security;

revoke all on table public.signup_codes from anon, authenticated;
grant all on table public.signup_codes to service_role;

